#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=5

# Every value belongs to the repo root, wherever the wizard was invoked from.
cd "$(dirname "${BASH_SOURCE[0]}")/.."

# claudebox is headless and reached over SSH, so there is no browser to open
# and xdg-open would either fail or hijack the terminal with a text browser.
# Show the URL prominently instead; most terminals make it clickable.
show_url() {
  if [[ -n "${DISPLAY:-}" || -n "${WAYLAND_DISPLAY:-}" ]] \
     || command -v wslview >/dev/null 2>&1 \
     || command -v explorer.exe >/dev/null 2>&1; then
    open_url "$1"
  else
    printf '  %s↗ im Browser öffnen:%s %s%s%s\n' "$GREEN" "$RESET" "$BOLD" "$1" "$RESET"
    note "   (Strg-Klick in den meisten Terminals, sonst kopieren)"
  fi
}

banner "Open Cloud einrichten"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Wem gehören die Assets?"
say "Alles, was der Agent hochlädt, gehört einem Roblox-Konto oder einer Gruppe."
say "Für den Anfang ist dein eigenes Konto das Richtige."
say ""
show_url "https://www.roblox.com/home"
step "Oben rechts auf deinen Avatar klicken, dann auf 'Profile'."
step "Adresszeile: roblox.com/users/ZAHL/profile — die ZAHL ist es."
say ""
ask ROBLOX_CREATOR_ID "Deine Roblox-User-ID:"
write_env ROBLOX_CREATOR_ID "$ROBLOX_CREATOR_ID"
write_env ROBLOX_CREATOR_TYPE "User"
note "Soll das Spiel später einer Gruppe gehören, ändern wir die zwei Zeilen in"
note ".env von Hand — dann steht dort Group und die Gruppen-ID."
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Experience anlegen"
say "Der Container für das Spiel. Du brauchst ihn, damit ich später von claudebox"
say "aus veröffentlichen kann, ohne dass du Studio öffnest."
say ""
show_url "https://create.roblox.com/dashboard/creations"
step "'Create New Experience' anklicken (oder das '+' bei Experiences)."
step "Namen vergeben — 'roblox-game-ben' geht, änderbar ist er jederzeit."
step "Erstellen, dann die neue Experience öffnen."
step "Adresszeile: .../experiences/ZAHL/overview — das ist die Universe-ID."
say ""
ask ROBLOX_UNIVERSE_ID "Universe-ID:"
write_env ROBLOX_UNIVERSE_ID "$ROBLOX_UNIVERSE_ID"
say ""
step "Links auf 'Places', beim Startplatz auf die drei Punkte, 'Copy Place ID'."
ask ROBLOX_PLACE_ID "Place-ID des Startplatzes:"
write_env ROBLOX_PLACE_ID "$ROBLOX_PLACE_ID"
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "API-Key: Berechtigungen"
say "Der Key ist das, womit der Agent von claudebox aus hochlädt."
say "Diese Stage und die nächste sind dasselbe Formular — bleib einfach drauf."
say ""
show_url "https://create.roblox.com/dashboard/credentials"
step "'Create API Key' anklicken."
step "Name: roblox-game-ben-claudebox"
say ""
step "'Add API System' → 'Assets'. Dort beide Rechte setzen: Read und Write."
note "    (heissen an anderer Stelle asset:read und asset:write)"
step "Als Besitzer dein eigenes Konto wählen — die ID aus Stage 1."
say ""
step "Noch einmal 'Add API System' → die Berechtigung für Places."
note "    (je nach Ansicht 'Place Management' oder universe-place:write)"
note "    Dort die Experience aus Stage 2 auswählen. Damit kann ich später"
note "    veröffentlichen, ohne dass du Studio anfasst."
say ""
warn "Noch nicht speichern — die nächste Stage gehört zum selben Formular."
pause "Berechtigungen gesetzt? Enter."

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "API-Key: Allowlist und Key abholen"
PUBLIC_IP=$(curl -fsS --max-time 8 https://api.ipify.org 2>/dev/null || true)
if [[ -n "$PUBLIC_IP" ]]; then
  say "Die Anfragen kommen von claudebox, nicht von deinem Windows-PC."
  printf '  %sÖffentliche IP dieses Rechners:%s %s%s%s\n' \
    "$DIM" "$RESET" "$BOLD" "$PUBLIC_IP" "$RESET"
  say ""
  step "Bei 'Accepted IP Addresses' eintragen: ${PUBLIC_IP}/32"
  note "    Ändert sich deine Internet-IP, schlägt der Upload fehl — dann trägst"
  note "    du hier die neue ein. 0.0.0.0/0 ist bequemer, macht den Key aber"
  note "    überall gültig, wo er auftaucht."
else
  warn "Öffentliche IP nicht ermittelbar."
  step "Bei 'Accepted IP Addresses' eintragen: 0.0.0.0/0"
fi
say ""
step "Ablaufdatum setzen — 90 Tage ist ein guter Kompromiss."
step "Speichern, dann beim erzeugten Key auf 'Copy'."
warn "Der Key wird nach dem Schliessen der Seite nie wieder angezeigt."
say ""
ask_secret ROBLOX_API_KEY "Key einfügen (bleibt unsichtbar):"
write_env ROBLOX_API_KEY "$ROBLOX_API_KEY"
note ".env steht in .gitignore und wird nie committet."
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Key prüfen"
say "Wir schicken eine absichtlich unvollständige Anfrage an Open Cloud. Sie kann"
say "nichts anlegen — aber an der Fehlermeldung sieht man, ob der Key durchkommt."
say "Sonst merkst du das erst beim Spike, längst aus dem Dashboard raus."
say ""
HTTP_CODE=$(curl -s -o /dev/null -w '%{http_code}' --max-time 15 \
  -X POST "https://apis.roblox.com/assets/v1/assets" \
  -H "x-api-key: ${ROBLOX_API_KEY}" 2>/dev/null || true)
case "$HTTP_CODE" in
  400)
    printf '  %s✓ Der Key kommt durch.%s\n' "$GREEN" "$RESET"
    note "HTTP 400 heisst: Roblox hat dich erkannt und nur die leere Anfrage"
    note "abgelehnt. Genau das wollten wir sehen."
    ;;
  401)
    warn "HTTP 401 — der Key wird nicht akzeptiert."
    say "Vermutlich beim Einfügen etwas verloren, oder er ist schon abgelaufen."
    say "Leg im Dashboard einen neuen an und starte den Wizard noch einmal."
    SKIPPED+=("Key-Prüfung: 401, Key neu anlegen")
    ;;
  403)
    warn "HTTP 403 — erkannt, aber nicht erlaubt."
    say "Zwei wahrscheinliche Ursachen, in dieser Reihenfolge:"
    say "  1. Die IP-Allowlist. Diese Anfrage kam von ${PUBLIC_IP:-dieser Maschine}."
    say "  2. Bei der Assets-Berechtigung fehlt Read oder Write."
    say "Beides änderst du am bestehenden Key, ohne einen neuen anzulegen."
    SKIPPED+=("Key-Prüfung: 403, IP-Allowlist oder Assets-Rechte korrigieren")
    ;;
  000|"")
    warn "Keine Antwort von Roblox — Netzwerk oder Timeout."
    say "Der Key kann trotzdem stimmen; wir merken es beim Spike."
    SKIPPED+=("Key-Prüfung: keine Antwort, später wiederholen")
    ;;
  *)
    warn "Unerwartete Antwort: HTTP $HTTP_CODE"
    say "Sag mir diese Zahl, dann schaue ich nach, was sie bedeutet."
    SKIPPED+=("Key-Prüfung: unerwartetes HTTP $HTTP_CODE")
    ;;
esac
pause

finish
